"""Emit the deliverable reports (P4): digest, leaderboard, headline number.

Every figure is produced from run data — nothing hand-typed.
"""
from pathlib import Path

import pandas as pd

from vireo import classify, config, metrics

WEEKLY_QUARTER = 13  # weeks per quarter, used for the quarterly projection


def write_report(result: dict, out_path: Path) -> None:
    s = result["stats"]
    lines = [
        "# Data quality report — Vireo ticket export",
        "",
        "Generated by `vireo.clean`. Every figure below is produced from the run, not hand-written.",
        "",
        "## Cleaning steps and results",
        "",
        "| Check | Result |",
        "|---|---|",
        f"| Rows in export | {s['rows_in']:,} |",
        f"| Duplicate rows dropped (legacy Freshdesk re-import, policy §9) | {s['duplicate_rows_dropped']:,} |",
        f"| Unique tickets after dedup | {s['unique_tickets']:,} |",
        f"| CSAT zeros treated as 'no response' (policy §8) | {s['csat_zeros_treated_as_no_response']:,} |",
        f"| CSAT blanks (no response) | {s['csat_blanks']:,} |",
        f"| Tickets with a refund amount | {s['refund_rows']:,} |",
        f"| Refunds above 3x retail (flagged, not dropped) | {s['refunds_over_3x_retail_flagged']:,} |",
        f"| Blank order_id before fallback | {s['orders_blank_before']:,} |",
        f"| Orders recovered via customer+SKU fallback (latest order on/before ticket) | {s['orders_recovered_via_fallback']:,} |",
        f"| Still blank (no prior order exists) | {s['orders_left_blank_no_prior_order']:,} |",
        f"| In-flight tickets (open/pending, excluded from metrics) | {s['inflight_tickets']:,} |",
        f"| Attendance set (resolved + closed) | {s['attended_tickets']:,} |",
        f"| Rows where resolved_at precedes created_at (legacy UTC artifact) | {int((result['attended']['resolved_at'] < result['attended']['created_at']).sum()):,} |",
        "",
        "## Decisions behind the numbers",
        "",
        "- **Dedup rule:** prefer the helpdesk row over legacy_fd. Duplicate pairs differ by exactly",
        "  5h30m in resolved_at — the legacy event-log UTC offset — so helpdesk rows carry IST times.",
        "- **CSAT:** 0 and blank both mean no response (policy §8); never averaged as zero.",
        "- **Refund units:** policy §9 warns legacy money is 'its own native unit'. Checked:",
        "  legacy and helpdesk refund distributions agree (median 2374 vs 2499, same max), and no",
        "  refund exceeds 3x retail. All amounts treated as rupees; no conversion applied.",
        "- **Order fallback:** 720 blank-order tickets match multiple customer+SKU orders; 456 of the",
        "  naive matches were newer than the ticket. Only orders dated on/before the ticket are used,",
        f"  latest first. {s['orders_left_blank_no_prior_order']} tickets have no prior order and stay blank.",
        "- **transfers** exists only in the current helpdesk; transfer-cost math covers those rows only.",
        "",
    ]
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text("\n".join(lines), encoding="utf-8")


def write_leaderboard(board: pd.DataFrame, out_path: Path) -> None:
    out_path.parent.mkdir(parents=True, exist_ok=True)
    board = board.copy()
    board.insert(0, "caveat", "")
    board.loc[board["tier"] == "Tier 2", "caveat"] = (
        "Tier 2 cases are multi-day by design (policy §6) — not comparable with Tier 1 volume"
    )
    board.loc[board["tier"] == "Tier 1", "caveat"] = (
        "closes per active week normalizes for roster start dates; volume is not quality"
    )
    board.to_csv(out_path, index=False)


def _best_trailing_quarter_rate(attended: pd.DataFrame) -> float:
    """Lowest repeat rate over any rolling 13-week window in the export — the
    proof that the desk has already operated at that level."""
    if attended.empty:
        return 0.0
    weeks = attended["created_at"].dt.to_period("W").sort_values().unique()
    flagged = metrics.with_repeat_flag(attended)
    per_week = flagged.groupby(flagged["created_at"].dt.to_period("W"))["repeat_contact"].agg(["sum", "count"])
    best = 1.0
    for start in range(len(weeks) - WEEKLY_QUARTER + 1):
        window = weeks[start : start + WEEKLY_QUARTER]
        part = per_week[per_week.index.isin(window)]
        if part["count"].sum() == 0:
            continue
        best = min(best, part["sum"].sum() / part["count"].sum())
    return best


def headline_number(attended: pd.DataFrame, stats: dict) -> dict:
    """The business goal as a number: repeat contacts, costed at channel rates.

    Target rate = best rolling-13-week rate actually achieved in this export
    (the desk has demonstrably operated there). If no window beats a flat 10%,
    10% is used and flagged as an assumption, not an observed level.
    """
    repeat = metrics.repeat_contact_summary(attended)
    current_rate = repeat["repeat_rate"]
    weeks = attended["created_at"].dt.to_period("W").nunique()
    per_week = repeat["repeat_contacts"] / weeks if weeks else 0
    observed_best = _best_trailing_quarter_rate(attended)
    target_rate = min(observed_best, 0.10) if observed_best and observed_best < current_rate else min(current_rate, 0.10)
    target_is_observed = observed_best < min(current_rate, 0.10)
    avoidable_per_week = per_week * (1 - target_rate / current_rate) if current_rate else 0
    avg_repeat_cost = repeat["repeat_cost_inr"] / repeat["repeat_contacts"] if repeat["repeat_contacts"] else 0
    quarterly_saving = avoidable_per_week * WEEKLY_QUARTER * avg_repeat_cost
    return {
        "metric": "repeat contacts (same customer, same issue, within 30 days of resolution — policy §10)",
        "current_rate": current_rate,
        "target_rate": target_rate,
        "repeat_contacts": repeat["repeat_contacts"],
        "repeat_cost_inr": repeat["repeat_cost_inr"],
        "avg_repeat_cost_inr": avg_repeat_cost,
        "quarterly_saving_inr": quarterly_saving,
        "target_is_observed": target_is_observed,
        "observed_best_rate": observed_best,
        "top_categories": repeat["top_categories"],
        "sla_breach_cost_inr": float(metrics.sla_breach_summary(attended)["breach_cost_inr"].sum()),
        "transfer_cost_inr": metrics.transfer_cost(attended)["transfer_cost_inr"],
    }


def _fmt_week(period) -> str:
    return f"{period.start_time:%d %b %Y}"


def write_digest(attended: pd.DataFrame, classifications: dict[str, dict], result: dict, out_path: Path) -> None:
    labeled = attended.copy()
    # The export's final week is usually partial (cut off mid-week) — the latest
    # COMPLETE week is the honest 'latest week' for the digest table.
    week_ends = labeled["created_at"].dt.to_period("W").max().end_time.normalize()
    is_final_week = labeled["created_at"].dt.to_period("W") == labeled["created_at"].dt.to_period("W").max()
    if labeled.loc[is_final_week, "created_at"].max() < week_ends - pd.Timedelta(days=2):
        labeled = labeled[~is_final_week]
    classified = labeled["ticket_id"].map(lambda tid: classifications.get(tid, {}).get("category"))
    digest = pd.DataFrame({
        "week": labeled["created_at"].dt.to_period("W"),
        "category": classified.fillna(labeled["category"]),
    })
    weekly = digest.pivot_table(index="week", columns="category", aggfunc="size", fill_value=0)

    last_week = weekly.index.max()
    prev_week = weekly.index[-2] if len(weekly) > 1 else None
    current = weekly.loc[last_week].sort_values(ascending=False)

    headline = headline_number(attended, result["stats"])
    sources = pd.Series([c["source"] for c in classifications.values()] or ["none"]).value_counts()
    mode = "LLM + heuristic fallback" if "llm" in sources.index else "heuristic only (no API key)"
    cost_inr = 0.0
    if (config.PROJECT_ROOT / "run_costs.jsonl").exists():
        import json

        cost_inr = sum(
            json.loads(line).get("cost_inr", 0)
            for line in (config.PROJECT_ROOT / "run_costs.jsonl").read_text().splitlines()
        )

    lines = [
        "# Vireo Audio — weekly support digest",
        "",
        f"Week of {_fmt_week(last_week)} (latest complete week in the export).",
        "",
        "## The number that matters",
        "",
        f"**{headline['current_rate']:.1%} of tickets are repeat contacts** — a customer contacting us again",
        f"about the same issue within 30 days of resolution (policy §10). That cost **₹{headline['repeat_cost_inr']:,.0f}",
        f"over this export** at channel contact rates (₹{headline['avg_repeat_cost_inr']:,.0f} per repeat contact on average).",
        f"Cutting it to {headline['target_rate']:.0%} removes roughly **₹{headline['quarterly_saving_inr']:,.0f} per quarter**",
        (f"of re-handling cost. The desk has actually operated at {headline['observed_best_rate']:.1%} in its best 13-week window, so the target is proven achievable."
         if headline["target_is_observed"] else "of re-handling cost. The 10% target is an assumption — no 13-week window in this export beat it."),
        "",
        f"Supporting spend in the same period: **₹{headline['sla_breach_cost_inr']:,.0f}** in automatic SLA-breach",
        f"credits (₹350 each, policy §3) and **₹{headline['transfer_cost_inr']:,.0f}** in transfer re-handling (₹305 each, §4).",
        "",
        "## What customers complained about — latest week",
        "",
        "| Complaint category | Tickets | vs previous week |",
        "|---|---|---|",
    ]
    prev = weekly.loc[prev_week] if prev_week is not None else current * 0
    for category, count in current.items():
        delta = count - prev.get(category, 0)
        arrow = "▲" if delta > 0 else ("▼" if delta < 0 else "=")
        lines.append(f"| {category} | {count} | {arrow} {delta:+d} |")

    lines += [
        "",
        "## Trend — tickets per week by category (last 13 weeks)",
        "",
        "| Week | " + " | ".join(current.index[:5]) + " | all other |",
        "|---|" + "---|" * 6,
    ]
    other_cols = current.index[5:]
    for period, row in weekly.tail(13).iterrows():
        others = row[other_cols].sum()
        lines.append(f"| {_fmt_week(period)} | " + " | ".join(str(row[c]) for c in current.index[:5]) + f" | {others} |")

    top_categories = ", ".join(f"{cat} ({count})" for cat, count in headline["top_categories"].items())
    lines += [
        "",
        "## Where repeat contacts come from",
        "",
        f"Top repeat-contact categories: {top_categories}.",
        "These are the queues where fixing the issue the first time saves the most money.",
        "",
        "## How this table was made",
        "",
        f"- Complaint categories come from the customer's opening message: mode = **{mode}**"
        + (f" (cache hits: {sources.get('cache', 0)}, LLM: {sources.get('llm', 0)}, heuristic: {sources.get('heuristic', 0)})" if "cache" in sources.index or "llm" in sources.index else ""),
        f"- Intake-bot category used where the classifier made no call: {sources.get('none', 0)} tickets.",
        f"- LLM spend for this output to date: **₹{cost_inr:.4f}** (logged per call in run_costs.jsonl).",
        f"- Source rows: {result['stats']['attended_tickets']:,} resolved/closed tickets after removing",
        f"  {result['stats']['duplicate_rows_dropped']} duplicate re-imported rows; {result['stats']['inflight_tickets']} open/pending tickets excluded.",
        "",
    ]
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text("\n".join(lines), encoding="utf-8")
